const safe = (s) => (s || '').replace(/'/g, "''");
const d = $('Trigger').item.json;
const subtipoMap = {"4.1":{"label":"Problemas com Ramal","catId":37},"4.2":{"label":"Aparelho Telefônico","catId":38},"4.3":{"label":"Celular e Chip","catId":39},"4.4":{"label":"Outros","catId":40}};
const info = subtipoMap[d.subtipo] || {label:d.subtipo||'Telefonia',catId:14};
const prioMap = {baixa:1,media:2,alta:3,muito_alta:4};
