  '<p><strong>Bairro:</strong> ' + (d.bairro||'') + ' | Cidade: ' + (d.cidade||'') + ' | UF: ' + (d.uf||'') + ' | CEP: ' + (d.cep||'') + '</p>',
  '<p><strong>Celular Contato:</strong> ' + (d.celular_contato||'') + '</p>',
  '<p><strong>Telefone Unidade:</strong> ' + (d.telefone_unidade||'') + '</p>',
  '<p><strong>E-mail Unidade:</strong> ' + (d.email_unidade||'') + '</p>',
  d.email_coordenadoria ? '<p><strong>E-mail Coordenadoria:</strong> ' + d.email_coordenadoria + '</p>' : '',
  d.email_gerencia      ? '<p><strong>E-mail Gerência:</strong> ' + d.email_gerencia + '</p>' : '',
  d.email_secretaria    ? '<p><strong>E-mail Secretaria:</strong> ' + d.email_secretaria + '</p>' : '',
  '<p><strong>Setor:</strong> ' + (d.setor||'') + '</p>',
  d.protocolo_atendimento ? '<p><strong>Protocolo:</strong> ' + d.protocolo_atendimento + '</p>' : '',
  '<p><strong>Linha com Defeito:</strong> ' + (d.linha_defeito||'') + '</p>',
  '<p><strong>Ramal com Defeito:</strong> ' + (d.ramal_defeito||'') + '</p>',
  '<p><strong>Sala da Linha/Ramal:</strong> ' + (d.sala_linha_ramal||'') + '</p>',
  d.mac_aparelho ? '<p><strong>MAC do Aparelho:</strong> ' + d.mac_aparelho + '</p>' : '',
